INSERT INTO `articles` (`id`, `title`, `slug`, `type`, `excerpt`, `content`, `featured_image`, `category_id`, `author`, `status`, `published_at`, `seo_title`, `seo_description`, `canonical_url`, `og_image`, `faqs`, `selection_criteria`, `created_at`, `updated_at`) VALUES
(1, 'Best GPUs Under ৳100,000 in Bangladesh (2026)', 'best-gpus-under-100000-bd', 'guide', 'Real benchmark-per-taka picks for 1080p and 1440p gaming — with live price comparison across BD stores.', '<p>GPU pricing in Bangladesh swings week to week depending on import channels and stock. Below are the cards that consistently deliver the best frames per taka <em>at current Tulona-tracked prices</em>.</p><h3>What to check before buying</h3><p>Confirm warranty channel (official vs grey import), because that alone can change the effective value by 15%.</p>', NULL, NULL, 'Tulona Hardware Desk', 'published', '2026-08-27 11:13:25', 'Best GPUs Under ৳100,000 in Bangladesh — Compared', 'Data-backed GPU recommendations under ৳100k: what we picked, what we skipped, and why.', NULL, NULL, '[{"question":"Do you update these prices?","answer":"Yes \\u2014 every price on the linked product pages reflects our latest tracked data from partner stores."},{"question":"Is a grey-import card worth saving \\u09f38,000?","answer":"Usually not in Bangladesh: local warranty service can be decisive for expensive components."}]', '["1080p\\/1440p real-world performance","Local warranty availability","Live multi-store price on Tulona"]', '2026-08-29 11:13:25', '2026-08-29 11:13:25'),
(2, 'iPhone 17 Pro Review: The Boring Upgrade That Mostly Makes Sense', 'iphone-17-pro-review', 'review', 'After three weeks with Apple’s latest Pro: who should upgrade, who should absolutely not, and where to buy it cheapest in BD.', '<h2>Overview</h2><p>The 17 Pro refines rather than reinvents. Battery life is genuinely better; the camera system is iterative.</p><h2>Who shouldn’t buy it</h2><p>If you own an iPhone 15 Pro, nothing here justifies the price delta.</p>', NULL, NULL, 'Tulona Mobile Desk', 'published', '2026-08-22 11:13:25', NULL, NULL, NULL, NULL, '[{"question":"Does it support Bangla keyboard well?","answer":"Yes, iOS ships a native Avro-style phonetic layout."}]', '["3 weeks of daily-driver use","Battery logging with local SIMs","Price tracked across 4 stores"]', '2026-08-29 11:13:25', '2026-08-29 11:13:25');
