(16, 332, NULL, 'ইংলিশে দুর্বলদের জন্য - English Therapy', 'inglise-durwlder-jnz-english-therapy', NULL, NULL, NULL, 'physical', 'বইটির বৈশিষ্ট্যমুখের জড়তা কাটানোর ভোকাল এক্সারসাইজ।প্রতিটি লেসন ভিত্তিক রেকর্ডেড ভিডিও ক্লাস।সমস্যা সমাধানের জন্য ফ্রি লাইভ ক্লাস।হাজার হাজার বাক্য তৈরি করার সহজ কৌশল।প্রয়োজনীয় সকল ভোকাবুলারীর সমাহার।', 'বইটির বৈশিষ্ট্যমুখের জড়তা কাটানোর ভোকাল এক্সারসাইজ।প্রতিটি লেসন ভিত্তিক রেকর্ডেড ভিডিও ক্লাস।সমস্যা সমাধানের জন্য ফ্রি লাইভ ক্লাস।হাজার হাজার বাক্য তৈরি করার সহজ কৌশল।প্রয়োজনীয় সকল ভোকাবুলারীর সমাহার।', NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'published', '2026-08-29 13:58:25', '2026-08-29 13:58:25', NULL, 1),
(17, 332, NULL, 'সহজ ভাষায় ইংলিশ গ্রামার', 'shj-vashay-inglis-gramar', NULL, NULL, NULL, 'physical', 'বইটি সহজ ও সাবলীল বাংলা ভাষায় লেখা।বিশেষভাবে ইংলিশে দুর্বলদের জন্য সাজানো।পর্যাপ্ত উদাহরণ ও এক্সারসাইজ সংযোজিত।বেসিক টু এডভান্স পুর্ণাঙ্গ রেফারেন্স বই।সহজ সংজ্ঞা ও সহজ বাংলায় ব্যাখ্যা করা।কঠিন টার্মগুলোর শর্টকার্ট মেথড সংবলিত।', 'বইটি সহজ ও সাবলীল বাংলা ভাষায় লেখা।বিশেষভাবে ইংলিশে দুর্বলদের জন্য সাজানো।পর্যাপ্ত উদাহরণ ও এক্সারসাইজ সংযোজিত।বেসিক টু এডভান্স পুর্ণাঙ্গ রেফারেন্স বই।সহজ সংজ্ঞা ও সহজ বাংলায় ব্যাখ্যা করা।কঠিন টার্মগুলোর শর্টকার্ট মেথড সংবলিত।', NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'published', '2026-08-29 13:58:46', '2026-08-29 13:58:46', NULL, 1),
