(19, 332, NULL, 'জোছনা ও জননীর গল্প', 'jochna-oo-jnneer-glp', NULL, NULL, NULL, 'physical', 'ফ্ল্যাপে লেখা কিছু কথা জোছনা ও জননীর গল্প বাংলাদেশের স্বাধীনতা যুদ্ধের উপর ভিত্তি করে হুমায়ুন আহমেদ রচিত একটি উপন্যাস। মুক্তির মন্দির সোপানতলে কত প্রাণ হলো বলিদান, লেখা আছে অশ্রুজলে। কত বিপ্লবী বন্ধুর রক্তে রাঙা, বন্দিশালার ঐ শিকলভাঙা তারা কি ফিরিবে আর সুপ্রভাতে ? যত তরুণ অরুণ গেছে অস্তাচলে যারা স্বর্গগত তারা এখনো জানে, স্বর্গের চেয়ে প্রিয় জন্মভুমি এসো স্বদেশ ব্রতের মহাদীক্ষা লভি, সেই মৃত্যুঞ্জয়ীদের চরণ চুমি। যারা জীর্ণ জাতির বুকে জাগালো আশা, মৌন মলিন মুখে জাগালো ভাষা। সেই রক্তকমলে গাঁথা মাল্যখ...', 'ফ্ল্যাপে লেখা কিছু কথা জোছনা ও জননীর গল্প বাংলাদেশের স্বাধীনতা যুদ্ধের উপর ভিত্তি করে হুমায়ুন আহমেদ রচিত একটি উপন্যাস। মুক্তির মন্দির সোপানতলে কত প্রাণ হলো বলিদান, লেখা আছে অশ্রুজলে। কত বিপ্লবী বন্ধুর রক্তে রাঙা, বন্দিশালার ঐ শিকলভাঙা তারা কি ফিরিবে আর সুপ্রভাতে ? যত তরুণ অরুণ গেছে অস্তাচলে যারা স্বর্গগত তারা এখনো জানে, স্বর্গের চেয়ে প্রিয় জন্মভুমি এসো স্বদেশ ব্রতের মহাদীক্ষা লভি, সেই মৃত্যুঞ্জয়ীদের চরণ চুমি। যারা জীর্ণ জাতির বুকে জাগালো আশা, মৌন মলিন মুখে জাগালো ভাষা। সেই রক্তকমলে গাঁথা মাল্যখানি, বিজয়লক্ষ্যি দেব তাদেরই গলে মুক্তিযুদ্ধ চলাকালীন সময়ে সঙ্ঘটিত তাঁর নিজ জীবনের এবং নিকট সম্পর্কিত ঘনিষ্ঠ বিভিন্ন ব্যক্তির বাস্তব অভিজ্ঞতার কথা তিনি উপন্যাসিক আঙ্গিকে এতে ফুটিয়ে তুলেছেন। বঙ্গবন্ধু শেখ মুজিবর রহমানসহ তৎকালীন কিছু উল্লেখযোগ্য রাজনৈতিক ব্যক্তিবর্গের ঘটনা তাঁর নিজস্ব দৃষ্টিকোণ থেকে উঠে এসেছে এই উপন্যাসটিতে।-মোহিনী চৌধুরী', NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'published', '2026-08-29 14:01:44', '2026-08-29 14:01:44', NULL, 1),
