(40, 348, NULL, 'হাবলুদের জন্য প্রোগ্রামিং', 'habluder-jnz-programing', NULL, NULL, NULL, 'physical', '\'হাবলুদের জন্য প্রোগ্রামিং\' বইটি কাদের জন্য যারা ভয়ের কারণে প্রোগ্রামিং শিখা শুরু করতেই পারে না। প্রোগ্রামিং কঠিন; সায়ন্সের স্টুডেন্ট বা ম্যাথে ভালো না হলে প্রোগ্রামিং শিখতে পারবে না মনে করে মুখ লুকিয়ে রাখে। তাদের জন্য গল্প আর মজার ছলে, চায়ের আড্ডার মাধ্যমে প্রোগ্রামিংয়ের বেসিক কনসেপ্টগুলো উপস্থাপন করা হয়েছে। তাছাড়া স্মার্টফোনে কোনকিছু ইনস্টল না করেই প্রোগ্রামিং প্রাকটিস করতে পারবে। আর যারা প্রোগ্রামিং শিখে কিছুটা এগিয়ে আছে, তারাও বইটি পড়ে প্রোগ্রামিংয়ের বেসিক কনসেপ্টগুলো ফকফকা করে নিতে পারবে।বই...', '\'হাবলুদের জন্য প্রোগ্রামিং\' বইটি কাদের জন্য যারা ভয়ের কারণে প্রোগ্রামিং শিখা শুরু করতেই পারে না। প্রোগ্রামিং কঠিন; সায়ন্সের স্টুডেন্ট বা ম্যাথে ভালো না হলে প্রোগ্রামিং শিখতে পারবে না মনে করে মুখ লুকিয়ে রাখে। তাদের জন্য গল্প আর মজার ছলে, চায়ের আড্ডার মাধ্যমে প্রোগ্রামিংয়ের বেসিক কনসেপ্টগুলো উপস্থাপন করা হয়েছে। তাছাড়া স্মার্টফোনে কোনকিছু ইনস্টল না করেই প্রোগ্রামিং প্রাকটিস করতে পারবে। আর যারা প্রোগ্রামিং শিখে কিছুটা এগিয়ে আছে, তারাও বইটি পড়ে প্রোগ্রামিংয়ের বেসিক কনসেপ্টগুলো ফকফকা করে নিতে পারবে।বইয়ের ভূমিকা যারা পরীক্ষায় ভালো নম্বর পায় না, যাদেরকে ভালো স্টুডেন্ট হিসেবে গণ্য করা হয় না, তাদেরকে পরোক্ষভাবে গাধা, বলদ বা হাবলু হিসেবে সম্বোধন করা হয়। এসব হাবলুরা পড়ালেখার মাঠে, চাকরির হাটে কিংবা প্রেমের ঘাটে, অনেকটাই পিছিয়ে থাকে।হাবলুরা পড়ালেখায় হাবলু হলেও, দুনিয়ার সবকিছুতে হাবলু না। ক্লাস ফাঁকি দেয়ার ফন্দি, শর্টকাটে পাশ করার পদ্ধতি, ফ্রেন্ডের পকেট থেকে টাকা খসানোর সিস্টেম, হাবলুদের চাইতে ভালো কেউ জানে না। তাদের পড়ালেখা মনে না থাকলেও, টিভি সিরিয়ালের কাহিনী, সিনেমার ডায়ালগ, ইন্টারনেটের চিপা-চাপার খবর ঠিকই মনে থাকে। এমনকি এসব জিনিসে চাল্লুদেরকেও পিছনে ফেলে দেয় তারা। সেজন্যই হাবলুদের মতো করে, চায়ের দোকানের আড্ডার ভাষা দিয়ে, প্রোগ্রামিংকে উপস্থাপন করা হয়েছে। যাতে হাবলুরা হাবলু স্টাইলে প্রোগ্রামিং-এর মজা পেয়ে এগিয়ে যেতে পারে।হাবলুগিরি দিয়েই চাল্লুদের পিছনে ফেলে দেয়ার দৃঢ় প্রত্যয়ে-ঝংকার মাহবুব, হাবলু দ্য গ্রেটwww.jhankarmahbub.comসূচি * প্রোগ্রাম খায়, পরে না মাথায় দেয়?* variable বুঝলে, হবে না পয়সা ব্যয়* প্রোগ্রামিং প্র্যাকটিস করে রাত পোহালে* string এর তালে নাচবে গরু গোয়ালে* নানীর if-else বুঝে লাফায় নানা* বিস্কুটের array খায় বিড়ালছানা* while লুপকে করলে মালিশ* for লুপ ডাকবে সালিশ* প্রেমের প্রপোজ করলে গোটা দশ হালি* function বুঝবে না- কোনটা বউ কোনটা শালী* দ্বিগুণ টাকা ধার করে পালালে* প্রোগ্রামিং ল্যাঙ্গুয়েজ খুঁজবে মামা শিয়ালে* হাসবে হাবলু বিজয় মিছিলেঝংকার মাহবুবের বইয়ের পাণ্ডুলিপি পড়ে আমি খুবই অবাক এবং আশান্বিত হয়েছি যে আমাদের পরবর্তী প্রজন্ম নানা বিষয়ে যথেষ্ট দক্ষতা অর্জন করেই বড় হচ্ছে। বইয়ের নামকরণ থেকে শুরু করে ব্যবহৃত ভাষা এবং ঢং সবই ভিন্ন ও আকর্ষনীয়। বইয়ের নাম ‘হাবলুদের জন্য প্রোগ্রামিং’ হলেও লেখক সন্দেহাতীতভাবে বিশ্বাস করেন যে আমাদের যেকোনো তরুনের জন্য প্রোগ্রামিং শেখা তেমন কোনো কঠিন কাজ নয়। প্রতিটি অধ্যায়ই লেখকের স্বতন্ত্র ভাষায়, ঢংয়ে খুবই হাল্কা মেজাজে উপভোগ্য কৌতুকের সঙ্গে উপস্থাপিত হয়েছে যাতে করে কোন \'হাবলু\'ই টের না পায় যে সে খুবই জটিল কিছু শিখতে যাচ্ছে। অনুশীলন করার জন্য বইতেই পর্যাপ্ত ফাঁকা জায়গা দেয়া আছে।আমি আশা করি আমাদের ছেলেমেয়েরা এই বইটি পড়ে যেমন প্রোগ্রামিংয়ের ভয় জয় করবে, ঠিক একইভাবে প্রোগ্রামিংয়ের বেশ কিছু ধারনাও আত্মস্থ করতে পারবে। আমি ঝংকার মাহবুবকে বইটি লেখার জন্য অভিনন্দন জানাই এবং তাঁর বইয়ের পাঠকদের মেধার অনুশীলনের মাধ্যমে শ্রেয়তর মস্তিষ্কের অধিকারী হয়ে বাংলাদেশকে সমৃদ্ধ করার আমন্ত্রণ রইল।ড. মোহাম্মদ কায়কোবাদঅধ্যাপক, কম্পিউটার সায়েন্স এন্ড ইঞ্জিনিয়ারিং বিভাগ,বাংলাদেশ প্রকৌশল বিশ্ববিদ্যালয় (বুয়েট)', NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'published', '2026-08-29 15:57:54', '2026-08-29 15:57:54', NULL, 0),
(41, 348, NULL, 'প্রোগ্রামিং কনটেস্ট ডেটা স্ট্রাকচার ও অ্যালগরিদম - মো: মাহবুবুল হাসান', 'programing-kntest-deta-strakcar-oo-azlgridm-mo-mahbubul-hasan', NULL, NULL, NULL, 'physical', 'লেখকঃ মো: মাহবুবুল হাসান, ক্যাটাগরিঃ প্রোগ্রামিং বেসিক বই, মূল্যঃ 419.0, লিংকঃ www.rokomari.com/book/117663 , সার সংক্ষেপঃ লেখক পরিচিতিমো: মাহবুবুল হাসান (শান্ত)-এর জন্ম ১৯৮৬ সালে। তিনি রাজশাহীর অগ্রণী বিদ্যালয় থেকে মাধ্যমিক ও নিউ গভঃ ডিগ্রী কলেজ থেকে উচ্চ মাধ্যমিক সম্পন্ন করেন। ২০০৩ সালের প্রথম জাতীয় গণিত অলিম্পিয়াডে একশোতে একশো পেয়ে সেকেন্ডারি ক্যাটাগরিতে চ্যাম্পিয', 'লেখকঃ মো: মাহবুবুল হাসান, ক্যাটাগরিঃ প্রোগ্রামিং বেসিক বই, মূল্যঃ 419.0, লিংকঃ www.rokomari.com/book/117663 , সার সংক্ষেপঃ লেখক পরিচিতিমো: মাহবুবুল হাসান (শান্ত)-এর জন্ম ১৯৮৬ সালে। তিনি রাজশাহীর অগ্রণী বিদ্যালয় থেকে মাধ্যমিক ও নিউ গভঃ ডিগ্রী কলেজ থেকে উচ্চ মাধ্যমিক সম্পন্ন করেন। ২০০৩ সালের প্রথম জাতীয় গণিত অলিম্পিয়াডে একশোতে একশো পেয়ে সেকেন্ডারি ক্যাটাগরিতে চ্যাম্পিয', NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'published', '2026-08-29 16:01:33', '2026-08-29 16:01:33', NULL, 0),
