(48, 348, NULL, 'কম্পিউটার প্রোগ্রামিং', 'kmpiutar-programing', NULL, NULL, NULL, 'physical', 'বিশ্ববাজারে ব্যাপক চাহিদা পূরণের লক্ষ্যে নতুন প্রজন্মকে প্রোগ্রামিং-এ দক্ষ করে গড়ে তুলতে সহজবোধ্য ভাষায় রচিত হয়েছে এই বইটি। নতুন প্রজন্মের অনেকেই আইটি ব্যবহার করে ভিডিও গেমস এ আসক্ত। এ আসক্তি থেকে বাঁচাতে হলে তাদেরকে স্কুল জীবন থেকেই কম্পিউটার প্রোগ্রামিং চর্চায় উৎসাহিত করতে হবে। তারা যদি একবার কোডিং এর মজা পায় তাহলে পরবর্তীতে দক্ষ প্রোগ্রামার হতে পারবে। এই উদ্দেশ্যেই  অত্যন্ত সহজভাবে উদাহরণের সাহায্যে লেখা হয়েছে বইটি। আশা করি বইটি নবীন—প্রবীণ সকল পাঠকের অনেক উপকারে আসবে।', 'বিশ্ববাজারে ব্যাপক চাহিদা পূরণের লক্ষ্যে নতুন প্রজন্মকে প্রোগ্রামিং-এ দক্ষ করে গড়ে তুলতে সহজবোধ্য ভাষায় রচিত হয়েছে এই বইটি। নতুন প্রজন্মের অনেকেই আইটি ব্যবহার করে ভিডিও গেমস এ আসক্ত। এ আসক্তি থেকে বাঁচাতে হলে তাদেরকে স্কুল জীবন থেকেই কম্পিউটার প্রোগ্রামিং চর্চায় উৎসাহিত করতে হবে। তারা যদি একবার কোডিং এর মজা পায় তাহলে পরবর্তীতে দক্ষ প্রোগ্রামার হতে পারবে। এই উদ্দেশ্যেই  অত্যন্ত সহজভাবে উদাহরণের সাহায্যে লেখা হয়েছে বইটি। আশা করি বইটি নবীন—প্রবীণ সকল পাঠকের অনেক উপকারে আসবে।', NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 'published', '2026-08-29 16:05:38', '2026-08-29 16:05:38', NULL, 0),
